$u=require_login();$cid=(int)$u['company_id'];$pdo=db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method!=='GET')verify_csrf();$action=(string)($_GET['action']??'products');
try{switch($action){
 case 'products':require_cap_v10('sales.read');$st=$pdo->prepare('SELECT * FROM v10_products WHERE company_id=? ORDER BY active DESC,name_fa,name_en');$st->execute([$cid]);json_response(['ok'=>true,'items'=>$st->fetchAll()]);
 case 'save_product':require_cap_v10('sales.write');$b=body_json();$id=(int)req($b,'id',0);$fa=trim((string)req($b,'name_fa',''));$en=trim((string)req($b,'name_en',''));if(!$fa&&!$en)json_response(['ok'=>false,'error'=>'name_required'],422);$fa=$fa?:$en;$en=$en?:$fa;$vals=[req($b,'sku')?:null,$fa,$en,req($b,'category'),req($b,'unit'),strtoupper((string)req($b,'currency','USD')),(float)req($b,'unit_price',0),!empty($b['active'])?1:0,req($b,'notes')];if($id)$pdo->prepare('UPDATE v10_products SET sku=?,name_fa=?,name_en=?,category=?,unit=?,currency=?,unit_price=?,active=?,notes=? WHERE id=? AND company_id=?')->execute([...$vals,$id,$cid]);else{$pdo->prepare('INSERT INTO v10_products(company_id,sku,name_fa,name_en,category,unit,currency,unit_price,active,notes) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$cid,...$vals]);$id=(int)$pdo->lastInsertId();}json_response(['ok'=>true,'id'=>$id]);
 case 'delete_product':require_cap_v10('sales.write');$b=body_json();$pdo->prepare('DELETE FROM v10_products WHERE id=? AND company_id=?')->execute([(int)req($b,'id',0),$cid]);json_response(['ok'=>true]);
 case 'targets':require_cap_v10('reports.read');$st=$pdo->prepare('SELECT t.*,u.name user_name FROM v10_sales_targets t JOIN users u ON u.id=t.user_id WHERE t.company_id=? ORDER BY t.period_start DESC,u.name');$st->execute([$cid]);json_response(['ok'=>true,'items'=>$st->fetchAll()]);
