 case 'delete_target':require_cap_v10('reports.write');$b=body_json();$pdo->prepare('DELETE FROM v10_sales_targets WHERE id=? AND company_id=?')->execute([(int)req($b,'id',0),$cid]);json_response(['ok'=>true]);
 case 'forecast':require_cap_v10('reports.read');$st=$pdo->prepare("SELECT u.id,u.name,COALESCE(t.target_amount,0) target_amount,COALESCE(t.currency,'USD') target_currency,COALESCE(SUM(CASE WHEN o.stage='won' THEN o.amount ELSE 0 END),0) won,COALESCE(SUM(CASE WHEN o.stage NOT IN('won','lost') THEN o.amount*o.probability/100 ELSE 0 END),0) weighted_pipeline FROM users u LEFT JOIN v10_sales_targets t ON t.user_id=u.id AND t.company_id=u.company_id AND CURDATE() BETWEEN t.period_start AND t.period_end LEFT JOIN opportunities o ON o.owner_id=u.id AND o.company_id=u.company_id AND o.currency=t.currency AND DATE(o.updated_at) BETWEEN t.period_start AND t.period_end AND NOT EXISTS(SELECT 1 FROM v10_record_deletions d WHERE d.company_id=o.company_id AND d.entity_type='opportunities' AND d.entity_id=o.id) WHERE u.company_id=? AND u.active=1 GROUP BY u.id,u.name,t.target_amount,t.currency ORDER BY won DESC,weighted_pipeline DESC");$st->execute([$cid]);json_response(['ok'=>true,'items'=>$st->fetchAll()]);
 case 'quote_detail':require_cap_v10('sales.read');$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT q.*,c.name customer_name,c.email customer_email,c.phone customer_phone FROM quotations q LEFT JOIN customers c ON c.id=q.customer_id WHERE q.id=? AND q.company_id=?');$st->execute([$id,$cid]);$q=$st->fetch();if(!$q)json_response(['ok'=>false,'error'=>'not_found'],404);$st=$pdo->prepare('SELECT qi.*,p.id product_id,p.name_fa product_name_fa,p.name_en product_name_en FROM quotation_items qi LEFT JOIN v10_quote_item_products qp ON qp.company_id=qi.company_id AND qp.quotation_item_id=qi.id LEFT JOIN v10_products p ON p.id=qp.product_id WHERE qi.company_id=? AND qi.quotation_id=? ORDER BY qi.id');$st->execute([$cid,$id]);json_response(['ok'=>true,'quote'=>$q,'items'=>$st->fetchAll()]);
 case 'save_quote_item':require_cap_v10('sales.write');$b=body_json();$id=(int)req($b,'id',0);$qid=(int)req($b,'quotation_id',0);$st=$pdo->prepare('SELECT id FROM quotations WHERE id=? AND company_id=?');$st->execute([$qid,$cid]);if(!$st->fetchColumn())json_response(['ok'=>false,'error'=>'quote_not_found'],404);$pid=(int)req($b,'product_id',0)?:null;$prod=null;if($pid){$st=$pdo->prepare('SELECT * FROM v10_products WHERE id=? AND company_id=?');$st->execute([$pid,$cid]);$prod=$st->fetch();if(!$prod)json_response(['ok'=>false,'error'=>'product_not_found'],422);}$desc=trim((string)req($b,'description',''));if($desc===''&&$prod)$desc=trim((string)($prod['name_fa']?:$prod['name_en']));if(!$desc)json_response(['ok'=>false,'error'=>'description_required'],422);$qty=(float)req($b,'qty',1);$unit=(string)req($b,'unit',$prod['unit']??'pcs');$price=(float)req($b,'unit_price',$prod['unit_price']??0);$discount=(float)req($b,'discount_percent',0);$tax=(float)req($b,'tax_percent',0);$gross=$qty*$price;$line=($gross*(1-$discount/100))*(1+$tax/100);$vals=[$desc,$qty,$unit,$price,$discount,$tax,$line];if($id){$pdo->prepare('UPDATE quotation_items SET description=?,qty=?,unit=?,unit_price=?,discount_percent=?,tax_percent=?,line_total=? WHERE id=? AND company_id=? AND quotation_id=?')->execute([...$vals,$id,$cid,$qid]);$pdo->prepare('DELETE FROM v10_quote_item_products WHERE company_id=? AND quotation_item_id=?')->execute([$cid,$id]);}else{$pdo->prepare('INSERT INTO quotation_items(company_id,quotation_id,description,qty,unit,unit_price,discount_percent,tax_percent,line_total) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$cid,$qid,...$vals]);$id=(int)$pdo->lastInsertId();}if($pid)$pdo->prepare('INSERT INTO v10_quote_item_products(company_id,quotation_item_id,product_id) VALUES(?,?,?)')->execute([$cid,$id,$pid]);$pdo->prepare('UPDATE quotations SET subtotal=(SELECT COALESCE(SUM(qty*unit_price),0) FROM quotation_items WHERE company_id=? AND quotation_id=?),discount_amount=(SELECT COALESCE(SUM(qty*unit_price*discount_percent/100),0) FROM quotation_items WHERE company_id=? AND quotation_id=?),tax_amount=(SELECT COALESCE(SUM((qty*unit_price*(1-discount_percent/100))*tax_percent/100),0) FROM quotation_items WHERE company_id=? AND quotation_id=?),amount=(SELECT COALESCE(SUM(line_total),0) FROM quotation_items WHERE company_id=? AND quotation_id=?) WHERE id=? AND company_id=?')->execute([$cid,$qid,$cid,$qid,$cid,$qid,$cid,$qid,$qid,$cid]);json_response(['ok'=>true,'id'=>$id]);
 case 'delete_quote_item':require_cap_v10('sales.write');$b=body_json();$id=(int)req($b,'id',0);$qid=(int)req($b,'quotation_id',0);$pdo->prepare('DELETE FROM quotation_items WHERE id=? AND quotation_id=? AND company_id=?')->execute([$id,$qid,$cid]);$pdo->prepare('UPDATE quotations SET subtotal=(SELECT COALESCE(SUM(qty*unit_price),0) FROM quotation_items WHERE company_id=? AND quotation_id=?),discount_amount=(SELECT COALESCE(SUM(qty*unit_price*discount_percent/100),0) FROM quotation_items WHERE company_id=? AND quotation_id=?),tax_amount=(SELECT COALESCE(SUM((qty*unit_price*(1-discount_percent/100))*tax_percent/100),0) FROM quotation_items WHERE company_id=? AND quotation_id=?),amount=(SELECT COALESCE(SUM(line_total),0) FROM quotation_items WHERE company_id=? AND quotation_id=?) WHERE id=? AND company_id=?')->execute([$cid,$qid,$cid,$qid,$cid,$qid,$cid,$qid,$qid,$cid]);json_response(['ok'=>true]);
 case 'send_quote':require_cap_v10('communications.write');$b=body_json();$qid=(int)req($b,'quotation_id',0);$q=v10_require_record('quotations',$qid,$cid);$st=$pdo->prepare('SELECT email customer_email,name customer_name FROM customers WHERE id=? AND company_id=?');$st->execute([$q['customer_id'],$cid]);$customer=$st->fetch();if(!$customer||!$customer['customer_email'])json_response(['ok'=>false,'error'=>'customer_email_missing'],422);$cfg=integration_settings($cid,'email');if(!$cfg['enabled'])json_response(['ok'=>false,'error'=>'email_not_configured'],422);$key=(string)envv('APP_KEY','');$base=rtrim((string)envv('APP_URL',''),'/');if(strlen($key)<32||!filter_var($base,FILTER_VALIDATE_URL)||!preg_match('#^https?://#i',$base))json_response(['ok'=>false,'error'=>'public_quote_link_not_configured'],422);$expires=time()+7*86400;$token=hash_hmac('sha256',$qid.'|'.$expires.'|'.$cid,$key);$url=$base.'/quote-pdf.php?id='.$qid.'&company='.$cid.'&expires='.$expires.'&token='.rawurlencode($token).'&pdf=1&lang='.rawurlencode((string)($u['lang']??'fa'));$body='Quotation '.$q['quote_no'].'<br><br><a href="'.e($url).'">Open quotation PDF</a>';[$ok,$msg]=smtp_send($cfg['settings'],$customer['customer_email'],'Quotation '.$q['quote_no'],$body);log_communication($cid,(int)$u['id'],'email',$customer['customer_email'],'Quotation '.$q['quote_no'],$body,$ok?'sent':'failed',$cfg['provider'],$ok?'':$msg);if($ok){$pdo->prepare("UPDATE quotations SET status='sent' WHERE id=? AND company_id=?")->execute([$qid,$cid]);v10_timeline('quotations',$qid,'email','Quotation sent','To '.$customer['customer_email'],'communication',null,(int)$u['id']);}json_response(['ok'=>$ok,'message'=>$msg],$ok?200:502);
 default:json_response(['ok'=>false,'error'=>'unknown_action'],404);
